    isLoggedIn?: boolean;
  }

  export function PaywallGate({
    requiredTier,
    previewBody,
    isLoggedIn = false,
  }: PaywallGateProps) {
    const tierLabel = requiredTier === 'basic' ? 'Basic' : 'Premium';

    return (
