// src/lib/nav.ts
export type NavLink = {
  label: string;
  href: string;
};

/**
 * Header navigation — the 5 primary destinations.
 * Auth CTAs (Log In / Join) are rendered separately by the Navbar component.
 */
export const HEADER_NAV_LINKS: NavLink[] = [
