  { label: 'Academy', href: '/academy' },
  { label: 'Downloads', href: '/downloads' },
  { label: 'Resources', href: '/resources' },
];

/**
 * Footer navigation — header links plus utility pages.
 */
export const FOOTER_NAV_LINKS: NavLink[] = [
  ...HEADER_NAV_LINKS,
  { label: 'Contact', href: '/contact' },
];
